import{_ as t,c as a,o as n,ae as i}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse(`{"title":"Return Detail (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-return-detail-gql","title":"Return Detail","description":"Full detail of a single return request — the returned item, images, status, order/customer context, whether it can be reopened, and the status transitions the admin may set next.","query":"query AdminReturn($id: ID!) {\\n  adminReturn(id: $id) {\\n    id\\n    _id\\n    orderId\\n    orderIncrementId\\n    orderStatus\\n    customerName\\n    customerEmail\\n    isGuest\\n    statusId\\n    statusTitle\\n    statusColor\\n    packageCondition\\n    information\\n    canReopen\\n    item\\n    images\\n    availableStatuses\\n    messagesCount\\n    createdAt\\n    updatedAt\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/rma/requests/12\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminReturn\\": {\\n      \\"id\\": \\"/api/admin/rma/requests/12\\",\\n      \\"_id\\": 12,\\n      \\"orderId\\": 45,\\n      \\"orderIncrementId\\": \\"000000045\\",\\n      \\"orderStatus\\": \\"processing\\",\\n      \\"customerName\\": \\"Jane Doe\\",\\n      \\"customerEmail\\": \\"jane@example.com\\",\\n      \\"isGuest\\": 0,\\n      \\"statusId\\": 1,\\n      \\"statusTitle\\": \\"Pending\\",\\n      \\"statusColor\\": \\"#FDB022\\",\\n      \\"packageCondition\\": \\"opened\\",\\n      \\"information\\": \\"Customer reported a defect.\\",\\n      \\"canReopen\\": false,\\n      \\"item\\": {\\n        \\"id\\": 30,\\n        \\"order_item_id\\": 78,\\n        \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n        \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n        \\"quantity\\": 1,\\n        \\"resolution\\": \\"return\\",\\n        \\"reason_id\\": 2,\\n        \\"reason\\": \\"Damaged product\\",\\n        \\"variant_id\\": null\\n      },\\n      \\"images\\": [\\n        {\\n          \\"id\\": 5,\\n          \\"path\\": \\"rma/12/damage-front.png\\",\\n          \\"url\\": \\"https://example.com/storage/rma/12/damage-front.png\\"\\n        }\\n      ],\\n      \\"availableStatuses\\": [\\n        { \\"id\\": 2, \\"title\\": \\"Accept\\" },\\n        { \\"id\\": 3, \\"title\\": \\"Declined\\" }\\n      ],\\n      \\"messagesCount\\": 2,\\n      \\"createdAt\\": \\"2026-07-20T10:15:30+00:00\\",\\n      \\"updatedAt\\": \\"2026-07-20T10:15:30+00:00\\"\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/returns/queries/view-return.md","filePath":"api/graphql-api/admin/sales/returns/queries/view-return.md"}`),r={name:"api/graphql-api/admin/sales/returns/queries/view-return.md"};function s(o,e,d,l,u,c){return n(),a("div",null,e[0]||(e[0]=[i('<h1 id="return-detail-graphql" tabindex="-1">Return Detail (GraphQL) <a class="header-anchor" href="#return-detail-graphql" aria-label="Permalink to &quot;Return Detail (GraphQL)&quot;">​</a></h1><p>Returns a single RMA request by IRI, with the returned item, proof images, status, order/customer context, the <code>canReopen</code> flag, and the <code>availableStatuses</code> transitions the admin may set next.</p><p>The <code>id</code> argument is the request IRI (<code>/api/admin/rma/requests/{id}</code>).</p><h2 id="field-notes" tabindex="-1">Field notes <a class="header-anchor" href="#field-notes" aria-label="Permalink to &quot;Field notes&quot;">​</a></h2><ul><li><code>item</code> is the returned line: <code>id</code>, <code>order_item_id</code>, <code>sku</code>, <code>name</code>, <code>quantity</code>, <code>resolution</code> (<code>return</code> or <code>cancel_items</code>), <code>reason_id</code>, <code>reason</code>, and <code>variant_id</code>. Select it bare (it is a JSON value).</li><li><code>images</code> is a list of <code>{ id, path, url }</code>.</li><li><code>availableStatuses</code> is a list of <code>{ id, title }</code> — the status ids you may pass to <a href="./../mutations/update-status.html">Update Status</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/graphql-api/admin/sales/returns/">Returns overview</a> for the status workflow and action semantics.</p></div><p>Permission: <code>sales.rma.requests</code>.</p><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',8)]))}const h=t(r,[["render",s]]);export{p as __pageData,h as default};
